.step-item.active .step-marker {
    background: #4361ee;
    color: white;
}

.step-item.completed .step-marker {
    background: #2ecc71;
    color: white;
}

.step-item.future .step-marker {
    background: #e0e0e0;
    color: #999;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
