@namespace sv_9193f02b05574fd1908734f6f0fb50d2.Components.Pages.Apply

<div class="work-entry-card">
    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="HandleCompanyChange" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="HandleTitleChange" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDateString" @onchange="HandleStartDateChange" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@EndDateString"
                   disabled="@IsCurrent"
                   @onchange="HandleEndDateChange" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="HandleDescriptionChange"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;
    private string StartDateString => Entry.StartDate.ToString("yyyy-MM-dd");
    private string EndDateString => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private Task HandleCompanyChange(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Company = e.Value?.ToString() ?? string.Empty });

    private Task HandleTitleChange(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Title = e.Value?.ToString() ?? string.Empty });

    private Task HandleStartDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        var date = string.IsNullOrEmpty(val) ? DateTime.Today : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(Entry with { StartDate = date });
    }

    private Task HandleEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        DateTime? endDate = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private Task HandleDescriptionChange(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Description = e.Value?.ToString() ?? string.Empty });

    private Task HandleCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        return OnEntryChanged.InvokeAsync(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }
}

